    if (Code == TEXT("de")) return De;
    if (Code == TEXT("es")) return Es;
    if (Code == TEXT("fr")) return Fr;
    if (Code == TEXT("hi")) return Hi;
    if (Code == TEXT("it")) return It;
    if (Code == TEXT("ja")) return Ja;
    if (Code == TEXT("ko")) return Ko;
    if (Code == TEXT("no")) return No;
